import{_ as t,o,c as a,ag as i}from"./chunks/framework.DQQHyi2x.js";const h=JSON.parse('{"title":"Multi-Provider and Codex CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/multi-provider-codex-v2.md","filePath":"guide/multi-provider-codex-v2.md"}'),d={name:"guide/multi-provider-codex-v2.md"};function r(s,e,l,n,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="multi-provider-and-codex-cli" tabindex="-1">Multi-Provider and Codex CLI <a class="header-anchor" href="#multi-provider-and-codex-cli" aria-label="Permalink to &quot;Multi-Provider and Codex CLI&quot;">​</a></h1><p>Claude Deck has moved from a Claude Code-only control surface to a provider-aware local agent dashboard. Claude Code remains the most complete provider. Codex CLI support is stable for sessions, safe configuration, diagnostics, MCP/plugin inventory, supported CLI-backed mutations, feature flags, and redacted exports. The UI is explicit about what is diagnostics-only and what is intentionally unavailable.</p><h2 id="provider-model" tabindex="-1">Provider Model <a class="header-anchor" href="#provider-model" aria-label="Permalink to &quot;Provider Model&quot;">​</a></h2><p>Provider status comes from <code>/api/v1/providers</code> and <code>/api/v1/providers/{provider_id}/status</code>.</p><p>Each provider reports:</p><ul><li>install state, binary path, and version when available</li><li>config paths used by the provider</li><li>capability flags used by the API and UI</li><li>provider-specific policy metadata, such as backup and restore behavior</li></ul><p>Boolean capability flags stay backward-compatible: unsupported or unavailable surfaces are <code>false</code>, not omitted. Newer provider-specific details live in metadata objects so older clients can continue using the boolean flags.</p><h2 id="capability-summary" tabindex="-1">Capability Summary <a class="header-anchor" href="#capability-summary" aria-label="Permalink to &quot;Capability Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Claude Code</th><th>Codex CLI</th></tr></thead><tbody><tr><td>Agent Bridge tmux discovery</td><td>Supported</td><td>Supported</td></tr><tr><td>Spawn/resume/fork</td><td>Spawn and resume; no fork</td><td>Spawn, resume, and fork</td></tr><tr><td>Config editing</td><td>JSON settings, scopes, permissions</td><td>Safe TOML scalar and feature edits</td></tr><tr><td>Config/profile diagnostics</td><td>Scope resolver</td><td>Profile and profile-file diagnostics</td></tr><tr><td>MCP inventory</td><td>Claude settings/API</td><td><code>codex mcp list --json</code></td></tr><tr><td>MCP mutation</td><td>Claude MCP pages</td><td>CLI-backed add/remove only</td></tr><tr><td>Plugin inventory</td><td>Supported</td><td><code>codex plugin list</code> inventory</td></tr><tr><td>Plugin install/remove</td><td>Supported</td><td>CLI-backed install/remove when supported by Codex CLI</td></tr><tr><td>Plugin enable/disable</td><td>Supported</td><td>Unsupported until Codex exposes a safe contract</td></tr><tr><td>History/session transcripts</td><td>Supported</td><td>Diagnostics-only investigation</td></tr><tr><td>Usage/context metrics</td><td>Supported</td><td>Unsupported</td></tr><tr><td>Backup/export</td><td>Backup and automatic restore</td><td>Redacted export only</td></tr><tr><td>Automatic restore</td><td>Supported</td><td>Refused</td></tr></tbody></table><h2 id="codex-supported-surfaces" tabindex="-1">Codex Supported Surfaces <a class="header-anchor" href="#codex-supported-surfaces" aria-label="Permalink to &quot;Codex Supported Surfaces&quot;">​</a></h2><p>Codex CLI support is productized for:</p><ul><li>mixed-provider Agent Bridge sessions with provider filters</li><li>provider status, version, config paths, and capability metadata</li><li>safe TOML settings edits for whitelisted scalar and feature fields</li><li>feature flag inventory and explicit overrides from <code>codex features list</code></li><li>config/profile diagnostics, including active/default profile resolution and malformed profile reporting</li><li>MCP inventory and CLI-backed MCP add/remove</li><li>plugin inventory and CLI-backed plugin install/remove where the local Codex CLI supports those commands</li><li><code>codex doctor</code> diagnostics with secret-like values redacted</li><li>redacted export-only backups</li></ul><h2 id="diagnostics-only-surfaces" tabindex="-1">Diagnostics-Only Surfaces <a class="header-anchor" href="#diagnostics-only-surfaces" aria-label="Permalink to &quot;Diagnostics-Only Surfaces&quot;">​</a></h2><p>Some local Codex files are useful for support diagnostics but are not stable product data sources.</p><p>History and model cache diagnostics may report file existence, size, parse status, root keys, row counts, and whether metric-like key names appear. They must not return prompt text, session ids, raw history rows, model ids, raw model cache payloads, auth data, or SQLite contents.</p><p>Usage and context parity are not supported for Codex. Claude Deck should not present Codex token usage, cost, billing block, or context-window metrics until Codex exposes a stable source that can be read without sensitive prompt or cache data.</p><h2 id="backup-and-restore-policy" tabindex="-1">Backup and Restore Policy <a class="header-anchor" href="#backup-and-restore-policy" aria-label="Permalink to &quot;Backup and Restore Policy&quot;">​</a></h2><p>Codex backups are redacted exports, not automatic restore points.</p><p>Codex exports may include:</p><ul><li><code>config.toml</code> with secret-like assignments redacted</li><li><code>*.config.toml</code> profile files with secret-like assignments redacted</li><li><code>rules/*.rules</code> files with secret-like assignments redacted</li><li>redacted provider inventory metadata</li></ul><p>Codex exports must exclude:</p><ul><li><code>auth.json</code></li><li><code>history.jsonl</code></li><li><code>models_cache.json</code></li><li>SQLite state and SQLite sidecar files</li><li>raw prompt text and raw cache payloads</li></ul><p>Automatic Codex restore is refused. The restore plan can show archive contents and refusal reasons, but the restore action must not extract files into <code>CODEX_HOME</code>.</p><h2 id="provider-errors" tabindex="-1">Provider Errors <a class="header-anchor" href="#provider-errors" aria-label="Permalink to &quot;Provider Errors&quot;">​</a></h2><p>Provider-specific operations should return normalized, user-actionable errors:</p><ul><li>unsupported capability</li><li>provider binary missing</li><li>command unavailable in the installed CLI</li><li>CLI execution failure with redacted stdout/stderr</li><li>parse failure with raw sensitive payloads omitted or redacted</li><li>validation failure for unsafe input</li></ul><p>The UI should use these states to disable unsupported controls rather than routing users to Claude-only pages while Codex is selected.</p><h2 id="smoke-coverage" tabindex="-1">Smoke Coverage <a class="header-anchor" href="#smoke-coverage" aria-label="Permalink to &quot;Smoke Coverage&quot;">​</a></h2><p>Multi-provider smoke coverage should exercise both providers in one run:</p><ul><li>provider registry returns Claude Code and Codex status without requiring both binaries to be installed</li><li>Agent Bridge can show mixed Claude Code and Codex tmux sessions together and can filter All, Claude Code, and Codex</li><li>Codex config, doctor, MCP, plugin, history/model-cache diagnostics, and backup export paths redact sensitive values</li><li>unsupported Codex usage/context and automatic restore states are visible and non-mutating</li><li>Claude-only pages remain hidden or disabled when Codex is selected</li></ul>',30)])])}const m=t(d,[["render",r]]);export{h as __pageData,m as default};
